// src/ProjectDetail.jsx
import React from "react";
import { useParams, useNavigate } from "react-router-dom";

// Données projets (même que Home.jsx)
const projects = [
  {
    id: "pos",
    title: "Système de Gestion de Points de Vente (POS)",
    description: (
      <>
        <p>
          Application web complète de gestion multi-magasins avec gestion des utilisateurs, produits, ventes, tableaux de bord et exports PDF/Excel.
        </p>
        <ul>
          <li>Gestion multi-utilisateurs avec rôles (admin/caissier)</li>
          <li>Gestion multi-points de vente</li>
          <li>Interface caissier simplifiée</li>
          <li>Dashboard analytique et reporting</li>
          <li>Export PDF/Excel</li>
        </ul>
      </>
    ),
    github: "https://github.com/tonrepo",
    demo: "https://tonapp.vercel.app",
    image:
      "https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=60",
  },
  {
    id: "autre-projet",
    title: "Autre Projet Exemple",
    description: <p>Description détaillée d’un autre projet.</p>,
    github: "#",
    demo: "#",
    image:
      "https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=60",
  },
];

export default function ProjectDetail() {
  const { id } = useParams();
  const navigate = useNavigate();

  const project = projects.find((p) => p.id === id);

  if (!project) return <p>Projet introuvable</p>;

  return (
    <div style={{ maxWidth: 700, margin: "auto", padding: 20, fontFamily: "Arial, sans-serif" }}>
      <button onClick={() => navigate(-1)} style={{ marginBottom: 20 }}>
        ← Retour
      </button>

      <h1>{project.title}</h1>
      <img
        src={project.image}
        alt={project.title}
        style={{ width: "100%", maxHeight: 300, objectFit: "cover", borderRadius: 8, marginBottom: 20 }}
      />
      <div>{project.description}</div>

      <p style={{ marginTop: 20 }}>
        <a href={project.github} target="_blank" rel="noreferrer" style={{ marginRight: 10 }}>
          Code source GitHub
        </a>
        <a href={project.demo} target="_blank" rel="noreferrer">
          Voir la démo
        </a>
      </p>
    </div>
  );
}
